    },
    {
      "card_ids": ["C12"],
      "claim": "Reboxetine, a moderately lipophilic ether/amine with high assay transfer (0.978), had absolute bioavailability 94.5% in humans, supporting essentially complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Labetalol, despite first-pass metabolism, showed oral bioavailability 63% in patients; other records range 25-44%, all above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Nabumetone, a lipophilic ketone prodrug with high assay transfer (0.981), had 38% absolute bioavailability of its active metabolite in healthy subjects, above threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Vorinostat, a polar hydroxamic acid with high assay transfer (0.981), had 43% oral bioavailability in fasting humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Ampicillin, a zwitterionic beta-lactam with high assay transfer (0.980), showed 62±17% oral bioavailability in healthy subjects, above threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Levothyroxine, a highly polar ionizable drug with high assay transfer (0.981), had 70-80% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 4-hydroxycoumarin (warfarin) with favorable physicochemical properties. All high-transfer experimental analogues have absolute oral bioavailability at or above 20%, many substantially higher, and none indicate low F. Therefore predict high.",
  "evidence_gaps": [
    "No direct bioavailability measurement for the query molecule itself in the supplied evidence; prediction relies on high-transfer analogues.",
    "Some analogues (labetalol, ampicillin, vorinostat) have moderate first-pass metabolism, but their F values remain above the 20% threshold."
  ],
